(function(){var loadHandler=window['sl_{046B8C57-CDC0-453C-8040-F71DF75FB288}'];loadHandler&&loadHandler(32, '<div id="spr0_515aa51"><div id="spr1_515aa51" class="kern slide"><img id="img3_515aa51" src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAA8AAAAIcAQMAAAADk1U4AAAAAXNSR0IArs4c6QAAAARnQU1BAACxjwv8YQUAAAADUExURR48hV/jvfAAAAAJcEhZcwAADsMAAA7DAcdvqGQAAABWSURBVHja7cExAQAAAMKg9U9tCF+gAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAeA3/PAAB2aB8vAAAAABJRU5ErkJggg==" width="1440px" height="810px" alt="" style="left:0px;top:0px;"/><div id="spr3_515aa51" aria-label="Padrão do plano de fundo" role="group" style="left:0px;top:0px;"><div id="spr4_515aa51"><img id="img0_515aa51" src="data:image/png;base64," width="1440" height="810" alt=""/></div></div></div><div id="spr2_515aa51" class="kern slide"><div id="spr5_515aa51" style="left:65.278px;top:57.869px;"><div style="width:0px;"><span id="txt0_515aa51" class="nokern" data-width="1199.343750" style="top:-10.819px;">Cancelamentos seguros e assistências</span></div></div><div id="svg3_515aa51" style="left:55.901px;top:121.672px;"><svg width="1216" height="18" viewBox="-9 -4.5 1216 18"><g fill="#ffdd00" stroke="none"><path stroke="#ffdd00" stroke-width="9" stroke-linecap="butt" transform="translate(-64.901367,-126.17244)" d="M64.901,130.672 H1262.4"/></g></svg></div><div id="spr6_515aa51" style="left:64.902px;top:174.396px;"><div style="width:0px;"><span id="txt1_515aa51" class="nokern" data-width="335.890625" style="top:-0.004px;">Atendimento em loja física</span></div><div style="width:0px;"><span id="txt2_515aa51" class="nokern" data-width="590.173828" style="top:33.596px;">Seguros e Assistências cancelados no sistema</span></div><div style="width:0px;"><span id="txt3_515aa51" class="nokern relpos" data-width="51.925781" style="top:67.196px;">SSS</span> <span id="txt4_515aa51" class="nokern relpos" data-width="413.355469" style="left:-0.01px;top:67.196px;"> (Sistema de Seguros e Serviços)</span></div><div style="width:0px;"><span id="txt5_515aa51" class="nokern" data-width="617.326172" style="top:134.396px;">Para a loja realizar o procedimento, é necessário:</span></div><div style="width:0px;"><span id="txt6_515aa51" class="nokern" data-width="560.000000" style="top:167.996px;">Cancelar o seguro e recolher a assinatura do</span></div><div style="width:0px;"><span id="txt7_515aa51" class="nokern" data-width="433.234375" style="top:201.596px;">cliente no termo de cancelamento;</span></div><div style="width:0px;"><span id="txt8_515aa51" class="nokern" data-width="492.324219" style="top:235.196px;">Verificar se gerou valor a ser restituído;</span></div><div style="width:0px;"><span id="txt9_515aa51" class="nokern" data-width="614.714844" style="top:268.796px;">Para devolver a restituição, efetivar a abertura de</span></div><div style="width:0px;"><span id="txt10_515aa51" class="nokern relpos" data-width="179.511719" style="top:302.396px;">ocorrência no </span> <span id="txt11_515aa51" class="nokern relpos" data-width="164.349609" style="left:-0.01px;top:302.396px;">Suporte Chat</span> <span id="txt12_515aa51" class="nokern relpos" data-width="215.523438" style="left:-0.02px;top:302.396px;"> para abertura do</span></div><div style="width:0px;"><span id="txt13_515aa51" class="nokern" data-width="306.140625" style="top:335.996px;">protocolo de restituição;</span></div><div style="width:0px;"><span id="txt14_515aa51" class="nokern" data-width="617.298828" style="top:369.596px;">Informar ao cliente o número do protocolo. Prazo</span></div><div style="width:0px;"><span id="txt15_515aa51" class="nokern relpos" data-width="204.380859" style="top:403.196px;">para restituição </span> <span id="txt16_515aa51" class="nokern relpos" data-width="191.283203" style="left:-0.01px;top:403.196px;">até 7 dias úteis</span> <span id="txt17_515aa51" class="nokern relpos" style="left:-0.02px;top:403.196px;">.</span></div><div style="width:0px;"><span id="txt18_515aa51" class="nokern" data-width="472.500000" style="top:470.396px;">IMPORTANTE: cliente pode solicitar o</span></div><div style="width:0px;"><span id="txt19_515aa51" class="nokern" data-width="411.140625" style="top:503.996px;">cancelamento à qualquer tempo!</span></div></div><div id="svg7_515aa51" style="top:677.821px;"><svg width="1440" height="133" viewBox="0 0 1440 133"><g fill="none"><path fill="#ffdd00" d="M0,132.179 L1440,0 V132.179 Z"/></g></svg></div><div id="spr7_515aa51" aria-label="Pefisa - Serviços financeiros" role="group" style="left:1295.457px;top:703.229px;"><div id="spr8_515aa51"><img id="img1_515aa51" src="data:image/png;base64," width="124.21" height="84.364" alt=""/></div></div><div id="spr9_515aa51" style="left:793.2px;top:129.904px;"><div id="spr10_515aa51"><img id="img2_515aa51" src="data:image/png;base64," width="561" height="561" alt="" style="left:-0.19px;top:-0.19px;"/></div></div></div></div>');})();